<script setup lang="ts">
import { accountPlatform, platformName, loginStatus } from '@/services/accounts';
import { computed, ref, watch } from 'vue';
import { useRouter } from 'vue-router';
import { studio } from '@/services/studio';
import { Dialog, DialogContent, DialogTitle, DialogDescription } from '@/components/ui';
import { toast } from 'vue-sonner';
const props = defineProps<{projectId:string}>(); const router=useRouter();
const project=computed(()=>studio.value.projects.find(p=>p.id===props.projectId)!); const name=ref(project.value.name); const desc=ref(project.value.desc); const confirm=ref('');
watch(()=>props.projectId,()=>{name.value=project.value.name;desc.value=project.value.desc;});
function save(){if(!name.value.trim()){toast.error('请填写项目名称');return;}project.value.name=name.value.trim();project.value.desc=desc.value;toast.success('项目资料已保存');}
function toggle(id:string){if(project.value.accountIds.includes(id)){const active=studio.value.tasks.some(t=>t.projectId===props.projectId&&t.accountId===id&&['待发布','已排期','发布中'].includes(t.status));if(active){toast.error('该帐号还有待执行任务，请先取消或等待完成');return;}project.value.accountIds=project.value.accountIds.filter(a=>a!==id);}else project.value.accountIds.push(id);}
function remove(){if(confirm.value==='delete'){studio.value.tasks.filter(t=>t.projectId===props.projectId&&['待配置','待发布','已排期'].includes(t.status)).forEach(t=>t.status='已取消');studio.value.projects=studio.value.projects.filter(p=>p.id!==props.projectId);void router.push('/');}else if(confirm.value==='archive'){project.value.archived=true;studio.value.tasks.filter(t=>t.projectId===props.projectId&&['待发布','已排期'].includes(t.status)).forEach(t=>{t.status='发布失败';t.error='项目已归档';});confirm.value='';void router.push('/');}}
</script>
<template><div class="max-w-4xl space-y-6"><section class="studio-card space-y-4"><h2 class="text-sm font-semibold">基本信息</h2><label class="block"><span class="studio-label">项目名称</span><input v-model="name" class="studio-field" maxlength="60"></label><label class="block"><span class="studio-label">项目描述</span><textarea v-model="desc" class="studio-field h-24 py-3" /></label><button class="studio-primary" @click="save">保存资料</button></section><section class="studio-card"><div class="mb-4 flex justify-between"><div><h2 class="text-sm font-semibold">关联帐号</h2><p class="mt-2 text-xs text-slate-400">帐号可跨项目复用，发布时仅显示本项目已关联的有效帐号</p></div><button class="text-xs text-sky-600" @click="router.push('/accounts')">管理授权与分组 ↗</button></div><label v-for="a in studio.accounts.filter(a=>!a.deleted && a.status!=='已解绑')" :key="a.id" class="flex items-center gap-3 border-t border-slate-100 py-4 text-sm"><input type="checkbox" :checked="project.accountIds.includes(a.id)" @change="toggle(a.id)"><span class="flex-1">{{a.name}} <span class="text-xs text-slate-400">{{a.handle}} · {{platformName(accountPlatform(a))}}</span></span><span class="studio-badge">{{loginStatus(a.status)}}</span></label><p v-if="!studio.accounts.some(a=>!a.deleted)" class="py-6 text-sm text-slate-400">暂无帐号，请先前往帐号管理授权。</p></section><section v-if="project.archived" class="studio-card"><h2 class="font-semibold">项目已归档</h2><button class="studio-primary mt-4" @click="project.archived=false;toast.success('项目已恢复')">恢复项目</button></section><section v-else class="studio-card flex items-center justify-between"><p class="text-xs text-slate-400">归档可恢复；删除项目保留平台发布记录，不删除平台内容。</p><div class="flex gap-3"><button class="studio-btn" @click="confirm='archive'">归档项目</button><button class="studio-btn !text-rose-500" @click="confirm='delete'">删除项目</button></div></section></div><Dialog :open="!!confirm" @update:open="!$event&&(confirm='')"><DialogContent class="max-w-md bg-white p-6"><DialogTitle>{{confirm==='delete'?'删除项目？':'归档项目？'}}</DialogTitle><DialogDescription>{{confirm==='delete'?'项目将从工作空间移除，待执行任务会取消。此操作不可恢复。':'归档后暂停未执行的发布任务，可在首页归档列表恢复。'}}</DialogDescription><button class="studio-primary" @click="remove">确认{{confirm==='delete'?'删除':'归档'}}</button></DialogContent></Dialog></template>
